// Questions from pi-durable extensions (`ui.ask`) as GitHub comments, and `ui.notify` as the log and job summary.
// pi-action is an asynchronous host: `ask` posts the question and returns at once. The answer (a ticked box, or an
// `/answer` reply) starts a later run, which delivers it to the thread (see answers.ts).
import type { GitHubClient } from "./github.ts";
import { sanitizeInput } from "./security.ts";
import type { DurableUi, Log, UiQuestion } from "./types.ts";
import { getErrorMessage } from "./utils.ts";

const MARKER_PREFIX = "<!-- pi-action:question";
/** Added to a question once it is answered; an open question has none. */
const ANSWERED_MARK = "<!-- pi-action:answered -->";
const KEY_PATTERN = /^[0-9a-f]{8,64}$/u;
const MARKER_PATTERN =
	/^<!-- pi-action:question ([0-9a-f]{8,64}) (confirm|select|input) -->/u;
const HEADING_PATTERN = /^### ❓ (.*)$/mu;
const ANSWER_PATTERN = /^\/answer(?:\s+|$)/iu;
const TASK_ITEM = /^\s*[-*+]\s+\[([ xX])\]\s+(.*?)\s*$/u;
const LINE_BREAK = /\r?\n/u;
const WHITESPACE_RUN = /\s+/gu;
const FOOTER_LINE = /^<sub>.*<\/sub>$/u;
const CONFIRM_OPTIONS: readonly string[] = ["Yes", "No"];
const NOTIFY_ICONS = { info: "ℹ️", warning: "⚠️", error: "❌" } as const;
const DEFAULT_TITLE = "pi has a question";

export const oneLine = (text: string): string =>
	text.replaceAll(WHITESPACE_RUN, " ").trim();

/** A checkbox label: one line, never empty (an empty task-list item is not a checkbox on GitHub). */
const optionLabel = (option: string): string => oneLine(option) || "(empty)";

/** Comments that belong to questions (pi-action's own, and `/answer` replies) are never `@pi` triggers. */
export function isQuestionComment(body: string): boolean {
	return body.includes(MARKER_PREFIX) || readAnswerReply(body) !== undefined;
}

/** A question comment as it reads now. */
export interface PostedQuestion {
	key: string;
	kind: UiQuestion["kind"];
	title: string;
	/** The task list (for confirm and select), in order, and which boxes are ticked. */
	options: string[];
	ticked: boolean[];
	answered: boolean;
}

/** The question in a comment body that starts with pi-action's marker; undefined for any other comment. */
export function parseQuestion(body: string): PostedQuestion | undefined {
	const marker = MARKER_PATTERN.exec(body.trimStart());
	const [, key, kind] = marker ?? [];
	if (
		key === undefined ||
		(kind !== "confirm" && kind !== "select" && kind !== "input")
	) {
		return undefined;
	}
	const items = body.split(LINE_BREAK).flatMap((line) => {
		const match = TASK_ITEM.exec(line);
		return match ? [{ ticked: match[1] !== " ", label: match[2] ?? "" }] : [];
	});
	return {
		key,
		kind,
		title: sanitizeInput(HEADING_PATTERN.exec(body)?.[1] ?? DEFAULT_TITLE),
		options: items.map((item) => item.label),
		ticked: items.map((item) => item.ticked),
		answered: body.includes(ANSWERED_MARK),
	};
}

/**
 * An `/answer <text>` reply: the answer (sanitized, the prefix removed) and the text the reply quotes first (GitHub's
 * "Quote reply" puts the quote before the answer). Undefined for any other comment.
 */
export function readAnswerReply(
	body: string,
): { text: string; quote: string } | undefined {
	const lines = sanitizeInput(body).split(LINE_BREAK);
	const start = lines.findIndex(
		(line) => line.trim() !== "" && !line.startsWith(">"),
	);
	const rest = start === -1 ? "" : lines.slice(start).join("\n").trim();
	const match = ANSWER_PATTERN.exec(rest);
	if (!match) {
		return undefined;
	}
	const quote = lines
		.slice(0, Math.max(start, 0))
		.map((line) => line.slice(1).trim())
		.join("\n")
		.trim();
	return { text: rest.slice(match[0].length).trim(), quote };
}

/** The message as a blockquote, so none of its lines can pass for one of the question's checkboxes. */
const quoted = (text: string | undefined): string[] =>
	text?.trim()
		? [
				...text
					.trim()
					.split(LINE_BREAK)
					.map((line) => `> ${line}`.trimEnd()),
				"",
			]
		: [];

/** The checkbox labels a confirm or select question shows. */
function labelsOf(question: UiQuestion): string[] {
	if (question.kind === "confirm") {
		return [...CONFIRM_OPTIONS];
	}
	return question.kind === "select"
		? question.options.map((option) => optionLabel(option))
		: [];
}

const CHECKBOX_FOOTER =
	"<sub>Tick one box to answer. pi continues in a new run when you do; this run has ended.</sub>";
const REPLY_FOOTER =
	"<sub>Reply with a comment that starts with `/answer` (only replies from people allowed to run pi count). pi continues in a new run when you do; this run has ended.</sub>";

/** What a question shows between its title and footer: a task list, or an example `/answer` reply. */
function questionBody(question: UiQuestion): string[] {
	if (question.kind !== "input") {
		return [
			...quoted(question.kind === "confirm" ? question.message : undefined),
			...labelsOf(question).map((label) => `- [ ] ${label}`),
		];
	}
	return question.placeholder?.trim()
		? [`For example: \`/answer ${oneLine(question.placeholder)}\``]
		: [];
}

export function renderQuestion(question: UiQuestion): string {
	const body = questionBody(question);
	return [
		`<!-- pi-action:question ${question.key} ${question.kind} -->`,
		`### ❓ ${oneLine(question.title) || DEFAULT_TITLE}`,
		"",
		...body,
		"",
		question.kind === "input" ? REPLY_FOOTER : CHECKBOX_FOOTER,
	].join("\n");
}

/** The question's body once answered: the footer replaced by the answer and who gave it, and the answered mark. */
export function answeredBody(
	body: string,
	answer: string,
	login: string,
): string {
	const lines = body
		.trimEnd()
		.split(LINE_BREAK)
		.filter((line) => !FOOTER_LINE.test(line.trim()));
	return [
		...lines,
		`**✅ Answered: ${oneLine(answer) || "(empty)"} by @${login}**`,
		ANSWERED_MARK,
	].join("\n");
}

export interface GitHubUiOptions {
	gh: GitHubClient;
	/** The issue or PR the questions are posted on. */
	issueNumber: number;
	log: Log;
	/** Appends Markdown to the job summary. */
	summary?: ((markdown: string) => Promise<void>) | undefined;
}

/** The UI, and the questions this run asked (their comment URLs, oldest first). */
export interface GitHubUi extends DurableUi {
	readonly asked: readonly string[];
}

/**
 * pi-durable questions as comments on the issue or PR. `ask` posts a task list (`confirm`, `select`) or a request for
 * an `/answer` reply (`input`) and returns its URL at once; a question already open with the same key is not posted
 * twice. `notify` goes to the log and the job summary, not to comments.
 */
export function createGitHubUi(options: GitHubUiOptions): GitHubUi {
	const { gh, issueNumber, log } = options;
	const asked: string[] = [];
	let summarized = false;

	/** The URL of the open question with this key, if one was posted before. */
	async function openQuestion(
		question: UiQuestion,
	): Promise<string | undefined> {
		const comments = await gh.listIssueComments(issueNumber);
		const open = comments.find((comment) => {
			const posted = parseQuestion(comment.body ?? "");
			return (
				posted?.key === question.key &&
				posted.kind === question.kind &&
				!posted.answered
			);
		});
		return open?.html_url;
	}

	return {
		asked,

		async ask(question) {
			if (!KEY_PATTERN.test(question.key)) {
				throw new Error(
					`Invalid question key ${JSON.stringify(question.key)}: expected 8 to 64 lowercase hex characters`,
				);
			}
			if (question.kind === "select" && question.options.length === 0) {
				throw new Error(
					`The question "${oneLine(question.title)}" has no options`,
				);
			}
			const title = oneLine(question.title);
			const open = await openQuestion(question);
			if (open !== undefined) {
				log.info(`Already asked on GitHub, still open: ${title} (${open})`);
				asked.push(open);
				return { url: open };
			}
			const posted = await gh.createComment(
				issueNumber,
				renderQuestion(question),
			);
			log.info(`Asked on GitHub: ${title} (${posted.url})`);
			asked.push(posted.url);
			return { url: posted.url };
		},

		notify(message, level = "info") {
			if (level === "info") {
				log.info(`pi: ${message}`);
			} else {
				log.warning(`pi (${level}): ${message}`);
			}
			const heading = summarized ? "" : "### pi notifications\n\n";
			summarized = true;
			options
				.summary?.(`${heading}- ${NOTIFY_ICONS[level]} ${oneLine(message)}\n`)
				.catch((error: unknown) => {
					log.warning(
						`Could not write the job summary: ${getErrorMessage(error)}`,
					);
				});
		},
	};
}
// Answers to questions from pi-durable extensions, from the webhook event of a new run: a box ticked on a question
// (`issue_comment` `edited`) or an `/answer` reply (`issue_comment` `created`). Each becomes one submission to the
// thread: a message for the model, placed as a `ui.answer` entry that pit returns when the program asks again.
import {
	answeredBody,
	oneLine,
	parseQuestion,
	type PostedQuestion,
	readAnswerReply,
} from "./github-ui.ts";
import { extractTriggerInfo, type GitHubClient, toUserType } from "./github.ts";
import { type Allowlists, validatePermissions } from "./security.ts";
import type { Trigger } from "./triggers.ts";
import type {
	GitHubComment,
	GitHubUser,
	Log,
	TriggerInfo,
	UiAnswer,
} from "./types.ts";
import { getErrorMessage } from "./utils.ts";

export const ANSWER_KIND = "ui.answer";
/** Roles that can edit pi-action's comments (and so tick its boxes). */
const WRITE_ROLES = new Set(["admin", "maintain", "write"]);

/** An answer, and the issue or PR it belongs to. */
export interface AnswerEvent {
	info: TriggerInfo;
	trigger: Trigger;
}

export interface AnswerOptions {
	gh: GitHubClient;
	allow: Allowlists;
	log: Log;
}

function field(value: unknown, ...path: string[]): unknown {
	let current = value;
	for (const key of path) {
		current =
			typeof current === "object" && current !== null
				? Reflect.get(current, key)
				: undefined;
	}
	return current;
}

const text = (value: unknown): string =>
	typeof value === "string" ? value : "";

/** What the event is for questions: a question comment that was edited, an `/answer` reply, or neither. */
export function questionEventKind(
	payload: Record<string, unknown>,
): "edit" | "reply" | undefined {
	if (field(payload, "issue") === undefined) {
		return undefined;
	}
	const body = text(field(payload, "comment", "body"));
	const action = field(payload, "action");
	if (action === "edited") {
		return parseQuestion(body) ? "edit" : undefined;
	}
	return action === "created" && readAnswerReply(body) ? "reply" : undefined;
}

/** The value pit gets, and how the answer is shown. */
function valueOf(
	question: PostedQuestion,
	index: number,
): { answer: boolean | string; shown: string } {
	const label = question.options[index] ?? "";
	return question.kind === "confirm"
		? { answer: index === 0, shown: label }
		: { answer: label, shown: label };
}

function answerTrigger(
	info: TriggerInfo,
	answer: UiAnswer,
	shown: string,
	from: {
		author: GitHubUser;
		commentId: number;
		questionId: number;
		createdAt: string;
	},
): AnswerEvent {
	const message = `**@${answer.by}** answered pi's question *${oneLine(answer.title)}* (${answer.url}): ${shown}`;
	return {
		info,
		trigger: {
			// One per question comment: a question asked again later (same key) is a new comment, and a new answer.
			key: `answer-${answer.key}-${from.questionId}`,
			source: "comment",
			issueNumber: info.issueNumber,
			commentId: from.commentId,
			author: from.author,
			text: message,
			task: message,
			createdAt: from.createdAt,
			url: answer.url,
			answer,
		},
	};
}

/** Whether `sender`, who edited pi-action's comment, may answer: write access, and the action's allowlists. */
async function mayTick(
	sender: GitHubUser,
	options: AnswerOptions,
): Promise<boolean> {
	if (sender.type === "Bot") {
		return validatePermissions(sender, "", options.allow);
	}
	if (
		options.allow.allowedUsers.length > 0 &&
		!validatePermissions(sender, "", options.allow)
	) {
		return false;
	}
	const role = await options.gh
		.getCollaboratorPermission(sender.login)
		.catch((error: unknown) => {
			options.log.warning(
				`Could not check @${sender.login}'s permission: ${getErrorMessage(error)}`,
			);
			return "none";
		});
	return WRITE_ROLES.has(role);
}

async function settle(
	gh: GitHubClient,
	comment: { id: number; body: string },
	shown: string,
	login: string,
	log: Log,
): Promise<void> {
	try {
		await gh.updateComment(
			comment.id,
			answeredBody(comment.body, shown, login),
		);
	} catch (error) {
		log.warning(
			`Could not mark the question answered: ${getErrorMessage(error)}`,
		);
	}
}

/** A box ticked on a question: the first box that was unticked before the edit and is ticked now. */
async function fromEdit(
	payload: Record<string, unknown>,
	info: TriggerInfo,
	options: AnswerOptions,
): Promise<AnswerEvent | undefined> {
	const { gh, log } = options;
	const commentId = Number(field(payload, "comment", "id"));
	const after = parseQuestion(text(field(payload, "comment", "body")));
	const before = parseQuestion(text(field(payload, "changes", "body", "from")));
	if (!(after && before) || before.key !== after.key || before.answered) {
		log.info("An edit of a question that is not a new answer; skipping");
		return undefined;
	}
	const sameOptions =
		before.options.length === after.options.length &&
		before.options.every((option, i) => option === after.options[i]);
	const index = after.ticked.findIndex(
		(ticked, i) => ticked && before.ticked[i] === false,
	);
	if (!sameOptions || index === -1) {
		log.info("No box was newly ticked on the question; skipping");
		return undefined;
	}
	const current = await gh.getComment(commentId);
	const now = parseQuestion(current.body ?? "");
	if (now?.key !== after.key || now.answered) {
		log.info(`The question ${info.url ?? ""} is already answered; skipping`);
		return undefined;
	}
	const login = text(field(payload, "sender", "login"));
	const sender: GitHubUser = {
		login,
		type: toUserType(text(field(payload, "sender", "type"))),
	};
	if (!(login && (await mayTick(sender, options)))) {
		log.warning(
			`@${login} ticked a box on ${info.url ?? "a question"} but may not answer (it takes write access and the allowed_* inputs); ignoring it`,
		);
		return undefined;
	}
	const { answer, shown } = valueOf(after, index);
	const url = info.url ?? current.html_url;
	log.info(`@${login} answered ${oneLine(after.title)} (${url}): ${shown}`);
	await settle(
		gh,
		{ id: commentId, body: current.body ?? "" },
		shown,
		login,
		log,
	);
	return answerTrigger(
		{ ...info, author: sender },
		{
			key: after.key,
			kind: after.kind,
			answer,
			by: login,
			url,
			title: after.title,
		},
		shown,
		{
			author: sender,
			commentId,
			questionId: commentId,
			createdAt:
				text(field(payload, "comment", "updated_at")) ||
				new Date().toISOString(),
		},
	);
}

/** The open `input` question a reply answers: the one it quotes, else the oldest one posted before it. */
function questionFor(
	comments: readonly GitHubComment[],
	replyId: number,
	quote: string,
): { comment: GitHubComment; question: PostedQuestion } | undefined {
	const open = comments.flatMap((comment) => {
		const question = parseQuestion(comment.body ?? "");
		return question?.kind === "input" &&
			!question.answered &&
			comment.id < replyId
			? [{ comment, question }]
			: [];
	});
	return (
		open.find(
			({ question }) => quote !== "" && quote.includes(question.title),
		) ?? open[0]
	);
}

/** 👍 on the reply that answered a question. */
async function thumbsUp(
	gh: GitHubClient,
	issueNumber: number,
	commentId: number,
	log: Log,
): Promise<void> {
	try {
		await gh.addReaction({ source: "comment", issueNumber, commentId }, "+1");
	} catch (error) {
		log.warning(`Could not react to the answer: ${getErrorMessage(error)}`);
	}
}

/** An `/answer` reply from someone allowed to run pi. */
async function fromReply(
	info: TriggerInfo,
	options: AnswerOptions,
): Promise<AnswerEvent | undefined> {
	const { gh, log } = options;
	const reply = readAnswerReply(info.triggerText);
	const replyId = info.commentId;
	if (reply === undefined || replyId === undefined) {
		return undefined;
	}
	if (
		!validatePermissions(info.author, info.authorAssociation, options.allow)
	) {
		log.warning(
			`Ignoring /answer from @${info.author.login}, who is not allowed to run pi`,
		);
		return undefined;
	}
	const found = questionFor(
		await gh.listIssueComments(info.issueNumber),
		replyId,
		reply.quote,
	);
	if (!found) {
		log.info("An /answer reply, but no question is waiting for one; skipping");
		return undefined;
	}
	const { comment, question } = found;
	const { login } = info.author;
	log.info(
		`@${login} answered ${oneLine(question.title)} (${comment.html_url})`,
	);
	await Promise.all([
		settle(
			gh,
			{ id: comment.id, body: comment.body ?? "" },
			reply.text,
			login,
			log,
		),
		thumbsUp(gh, info.issueNumber, replyId, log),
	]);
	return answerTrigger(
		info,
		{
			key: question.key,
			kind: question.kind,
			answer: reply.text,
			by: login,
			url: comment.html_url,
			title: question.title,
		},
		reply.text,
		{
			author: info.author,
			commentId: replyId,
			questionId: comment.id,
			createdAt: info.createdAt ?? new Date().toISOString(),
		},
	);
}

/**
 * The answer the event carries, after checking who gave it, with the question marked answered (and the reply 👍).
 * Undefined, with the reason in the log, when the event is not a valid new answer.
 */
export async function answerFromEvent(
	payload: Record<string, unknown>,
	options: AnswerOptions,
): Promise<AnswerEvent | undefined> {
	const kind = questionEventKind(payload);
	const info = kind ? extractTriggerInfo(payload) : null;
	if (!(kind && info)) {
		return undefined;
	}
	return kind === "edit"
		? fromEdit(payload, info, options)
		: fromReply(info, options);
}
import { mkdir, mkdtemp } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

import type { Extension } from "@earendil-works/pi-durable";
import { CodingTools } from "@earendil-works/pi-durable/tools";

import type { DurableExtensionFactory } from "./extensions.ts";
import type { DurableUi, Log } from "./types.ts";
import { getErrorMessage } from "./utils.ts";

export interface DurableExtensionsOptions {
	/** The workspace (the checked-out repository). */
	cwd: string;
	/** The `agent_dir` input, relative to the workspace; a temp dir under RUNNER_TEMP when unset. */
	agentDir: string | undefined;
	/** The `trust_project` input. */
	trustProject: boolean;
	/** The GitHub UI, in comment mode on an issue or PR. */
	ui: DurableUi | undefined;
	log: Log;
	env: Record<string, string | undefined>;
}

/** The `agent_dir` input, or a fresh directory under RUNNER_TEMP. */
async function agentDirectory(
	options: DurableExtensionsOptions,
): Promise<string> {
	if (options.agentDir) {
		const dir = resolve(options.cwd, options.agentDir);
		await mkdir(dir, { recursive: true });
		return dir;
	}
	const base = options.env["RUNNER_TEMP"] || tmpdir();
	await mkdir(base, { recursive: true });
	return mkdtemp(join(base, "pi-action-agent-"));
}

/**
 * Builds the pi-durable extensions the `extensions` input declared, with the run's host options, for the thread's
 * registry. Their names must not collide with each other or with pi-action's coding tools.
 */
export async function createDurableExtensions(
	factories: readonly DurableExtensionFactory[],
	options: DurableExtensionsOptions,
): Promise<Extension[]> {
	if (factories.length === 0) {
		return [];
	}
	const { cwd, trustProject, ui, log } = options;
	const agentDir = await agentDirectory(options);
	log.info(
		`pi-durable extensions: agent directory ${agentDir}, project ${trustProject ? "trusted" : "not trusted"}, ${ui ? "questions answered on GitHub" : "no UI"}`,
	);
	const names = new Set([CodingTools.name]);
	const extensions: Extension[] = [];
	for (const factory of factories) {
		let extension: Extension;
		try {
			// oxlint-disable-next-line eslint/no-await-in-loop -- extensions are created in order, as they were loaded
			extension = await factory.create({
				cwd,
				agentDir,
				trustProject,
				...(ui ? { ui } : {}),
				log: { info: log.info, warning: log.warning },
			});
		} catch (error) {
			throw new Error(
				`Could not create pi-durable extension ${factory.source}: ${getErrorMessage(error)}`,
				{ cause: error },
			);
		}
		if (names.has(extension.name)) {
			throw new Error(
				`pi-durable extension ${factory.source} is named "${extension.name}", which is already taken`,
			);
		}
		names.add(extension.name);
		log.info(
			`pi-durable extension ${extension.name} (${factory.source}): ${(extension.tools ?? []).map((tool) => tool.name).join(", ") || "no tools"}`,
		);
		extensions.push(extension);
	}
	return extensions;
}
